  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { k: 'neg', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) fail()
    if (t.t === 'num') { p++; return { k: 'num', v: t.v } }
    if (t.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) p++
        else {
          for (;;) {
            args.push(cmp())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            fail()
          }
        }
        return { k: 'call', name: t.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        p++
        const t2 = toks[p]
        if (!t2 || t2.t !== 'word') fail()
        p++
        return { k: 'range', a: t.v, b: t2.v }
      }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { k: 'bool', v: true }
      if (u === 'FALSE') return { k: 'bool', v: false }
      return { k: 'ref', a: t.v }
    }
    if (isOp('(')) {
      p++
