import { readFileSync } from 'node:fs'
import { parseSheet } from './sheet.js'
import { runValues, runDeps } from './eval.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}
const parsed = parseSheet(readFileSync(0, 'utf8'))
if (parsed.error) {
  process.stderr.write(parsed.error + '\n')
  process.exit(2)
}
process.stdout.write(args[0] === 'values' ? runValues(parsed.cells) : runDeps(parsed.cells))
